+++ b/src/report.js
@@ -0,0 +1,30 @@
+import { daysLeft, isExpired } from "./expiry.js";
+
+const byText = (a, b) => (a < b ? -1 : a > b ? 1 : 0);
+
+/** Summary of the shelf at `now`: totals, counts by tag, expiring soon and expired names. */
+export function buildReport(items, now = Date.now()) {
+  const fresh = [];
+  const expired = [];
+  for (const item of items) (isExpired(item, now) ? expired : fresh).push(item);
+
+  const counts = {};
+  for (const item of fresh)
+    for (const tag of new Set(item.tags || [])) counts[tag] = (counts[tag] || 0) + 1;
+  const byTag = {};
+  for (const tag of Object.keys(counts).sort(byText)) byTag[tag] = counts[tag];
+
+  const expiringSoon = fresh
+    .filter((item) => daysLeft(item, now) <= 3)
+    .sort((a, b) => Date.parse(a.expires) - Date.parse(b.expires) || byText(a.name, b.name))
+    .map((item) => item.name);
+
+  return {
+    generatedAt: new Date(now).toISOString(),
+    total: fresh.length,
+    units: fresh.reduce((sum, item) => sum + item.qty, 0),
+    byTag,
+    expiringSoon,
+    expired: expired.map((item) => item.name).sort(byText),
+  };
+}
